CREATE TABLE ld_schema(version integer PRIMARY KEY, applied_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE ld_source_budget(name text PRIMARY KEY,next_at timestamptz NOT NULL);
INSERT INTO ld_source_budget VALUES('ncbi',now());
CREATE TABLE ld_accounts(account_id uuid PRIMARY KEY, login text NOT NULL UNIQUE, password_hash text NOT NULL, enabled boolean NOT NULL DEFAULT true);
CREATE TABLE ld_sessions(token_hash text PRIMARY KEY, account_id uuid NOT NULL REFERENCES ld_accounts, csrf text NOT NULL, expires_at timestamptz NOT NULL);
CREATE INDEX ld_session_expiry ON ld_sessions(expires_at);
CREATE TABLE ld_libraries(library_id uuid PRIMARY KEY, owner_id uuid NOT NULL REFERENCES ld_accounts, name text NOT NULL, ready boolean NOT NULL DEFAULT true);
CREATE INDEX ld_library_owner ON ld_libraries(owner_id,library_id);
CREATE TABLE ld_records(library_id uuid NOT NULL REFERENCES ld_libraries, search_id text NOT NULL, metadata text NOT NULL, title text NOT NULL, ordinal bigint GENERATED BY DEFAULT AS IDENTITY, PRIMARY KEY(library_id,search_id));
CREATE TABLE ld_identifiers(library_id uuid NOT NULL, kind text NOT NULL, value text NOT NULL, search_id text NOT NULL, PRIMARY KEY(library_id,kind,value), UNIQUE(library_id,search_id,kind), FOREIGN KEY(library_id,search_id) REFERENCES ld_records);
CREATE TABLE ld_runs(library_id uuid NOT NULL REFERENCES ld_libraries, run_id text NOT NULL, input text NOT NULL, total integer NOT NULL DEFAULT 0, fetched integer NOT NULL DEFAULT 0, requested_limit integer NOT NULL, state text NOT NULL, reason text NOT NULL DEFAULT '', snapshot text NOT NULL DEFAULT '{}', PRIMARY KEY(library_id,run_id));
CREATE TABLE ld_results(library_id uuid NOT NULL, run_id text NOT NULL, search_id text NOT NULL, rank integer NOT NULL, PRIMARY KEY(library_id,run_id,search_id), FOREIGN KEY(library_id,run_id) REFERENCES ld_runs, FOREIGN KEY(library_id,search_id) REFERENCES ld_records);
CREATE TABLE ld_scopes(library_id uuid NOT NULL REFERENCES ld_libraries, scope_id text NOT NULL, run_id text, parent_id text, description text NOT NULL, PRIMARY KEY(library_id,scope_id), FOREIGN KEY(library_id,run_id) REFERENCES ld_runs, FOREIGN KEY(library_id,parent_id) REFERENCES ld_scopes DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE ld_members(library_id uuid NOT NULL, scope_id text NOT NULL, search_id text NOT NULL, rank bigint NOT NULL, selected boolean NOT NULL DEFAULT false, PRIMARY KEY(library_id,scope_id,search_id), FOREIGN KEY(library_id,scope_id) REFERENCES ld_scopes, FOREIGN KEY(library_id,search_id) REFERENCES ld_records);
CREATE INDEX ld_members_page ON ld_members(library_id,scope_id,rank);
CREATE TABLE ld_batches(library_id uuid NOT NULL, batch_id text NOT NULL, scope_id text NOT NULL, state text NOT NULL, template text NOT NULL, PRIMARY KEY(library_id,batch_id), FOREIGN KEY(library_id,scope_id) REFERENCES ld_scopes);
CREATE TABLE ld_items(library_id uuid NOT NULL, item_id text NOT NULL, batch_id text NOT NULL, search_id text NOT NULL, rank integer NOT NULL, state text NOT NULL, attempts integer NOT NULL DEFAULT 0, last_job_id text, reason text NOT NULL DEFAULT '', planned_name text NOT NULL, PRIMARY KEY(library_id,item_id), UNIQUE(library_id,batch_id,search_id), FOREIGN KEY(library_id,batch_id) REFERENCES ld_batches, FOREIGN KEY(library_id,search_id) REFERENCES ld_records);
CREATE TABLE ld_jobs(library_id uuid NOT NULL REFERENCES ld_libraries, job_id text NOT NULL, kind text NOT NULL CHECK(kind IN ('search','acquire')), run_id text, item_id text, search_id text, state text NOT NULL, reason text NOT NULL DEFAULT '', lease_token uuid, lease_until timestamptz, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(library_id,job_id), FOREIGN KEY(library_id,run_id) REFERENCES ld_runs, FOREIGN KEY(library_id,item_id) REFERENCES ld_items, FOREIGN KEY(library_id,search_id) REFERENCES ld_records);
CREATE INDEX ld_job_claim ON ld_jobs(state,created_at);
CREATE TABLE ld_events(library_id uuid NOT NULL REFERENCES ld_libraries, event_id text NOT NULL, job_id text, state text NOT NULL, reason text NOT NULL, occurred_at text NOT NULL, PRIMARY KEY(library_id,event_id));
CREATE TABLE ld_files(library_id uuid NOT NULL REFERENCES ld_libraries, hash text NOT NULL, bytes bigint NOT NULL, kind text NOT NULL, validation text NOT NULL, PRIMARY KEY(library_id,hash));
CREATE TABLE ld_article_files(library_id uuid NOT NULL, search_id text NOT NULL, hash text NOT NULL, acquired_at text NOT NULL, source_uri text NOT NULL, final_uri text NOT NULL, license text NOT NULL, PRIMARY KEY(library_id,search_id,hash), FOREIGN KEY(library_id,search_id) REFERENCES ld_records, FOREIGN KEY(library_id,hash) REFERENCES ld_files);
CREATE TABLE ld_publications(library_id uuid NOT NULL, job_id text NOT NULL, hash text NOT NULL, state text NOT NULL, info text NOT NULL, source_uri text NOT NULL, final_uri text NOT NULL, PRIMARY KEY(library_id,job_id), FOREIGN KEY(library_id,job_id) REFERENCES ld_jobs);
CREATE TABLE ld_legacy_rows(library_id uuid NOT NULL REFERENCES ld_libraries, table_name text NOT NULL, row_number bigint NOT NULL, data text NOT NULL, PRIMARY KEY(library_id,table_name,row_number));
INSERT INTO ld_schema(version) VALUES(1);
